import { useCallback, useEffect, useRef, useState } from 'react'
import './App.css'

const API_BASE = 'http://localhost:3001'
const WS_URL = 'ws://localhost:3001/stream'

function App() {
  const [logs, setLogs] = useState([])
  const [connectionState, setConnectionState] = useState('connecting') // connecting | open | closed
  const [busy, setBusy] = useState(null) // 'trigger' | 'reset' | null
  const socketRef = useRef(null)
  const terminalRef = useRef(null)
  const counterRef = useRef(0)

  const pushLog = useCallback((type, message) => {
    const id = ++counterRef.current
    const time = new Date().toLocaleTimeString()
    setLogs(prev => [...prev, { id, type, message, time }])
  }, [])

  // WebSocket connection
  useEffect(() => {
    let socket
    try {
      socket = new WebSocket(WS_URL)
    } catch (err) {
      pushLog('error', `Unable to open WebSocket: ${err.message}`)
      setConnectionState('closed')
      return
    }
    socketRef.current = socket
    setConnectionState('connecting')

    socket.onopen = () => setConnectionState('open')
    socket.onclose = () => setConnectionState('closed')
    socket.onerror = () => setConnectionState('closed')
    socket.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        pushLog(data.type ?? 'info', data.message ?? event.data)
      } catch {
        pushLog('info', event.data)
      }
    }

    return () => socket.close()
  }, [pushLog])
```

