```jsx
import { useCallback, useEffect, useRef, useState } from 'react'
import './App.css'

const SERVER_HTTP = 'http://localhost:3001'
const SERVER_WS = 'ws://localhost:3001/stream'

// Incident payload expected by the Fastify /trigger endpoint
const INCIDENT_PAYLOAD = {
  errorType: 'TypeError',
  file: 'src/cart.js',
  line: 3,
}

// Types understood by the terminal's color system
const LOG_LEVELS = ['alert', 'error', 'success', 'info']

function normalizeLevel(type) {
  return LOG_LEVELS.includes(type) ? type : 'system'
}

function App() {
  const [logs, setLogs] = useState([])
  const [connection, setConnection] = useState('connecting')
  const [pending, setPending] = useState(null)

  const socketRef = useRef(null)
  const terminalRef = useRef(null)
  const idRef = useRef(0)

  const pushLog = useCallback((type, message) => {
    const entry = {
      id: (idRef.current += 1),
      type: normalizeLevel(type),
      message,
      time: new Date().toLocaleTimeString('en-GB', { hour12: false }),
    }
    setLogs((prev) => [...prev, entry])
  }, [])

  // --- Live Telemetry: WebSocket link to the autonomous engine -----------
  useEffect(() => {
    let socket
    try {
      socket = new WebSocket(SERVER_WS)
    } catch (err) {
      pushLog('error', `Unable to open telemetry socket: ${err.message}`)
      setConnection('closed')
      return undefined
    }

    socketRef.current = socket

    socket.onopen = () => setConnection('open')
    socket.onclose = () => setConnection('closed')
    socket.onerror = () => setConnection('error')

    socket.onmessage = (event) => {
      let payload
      try {
        payload = JSON.parse(event.data)
      } catch {
        pushLog('info', String(event.data))
        return
      }
      pushLog(payload?.type, payload?.message ?? event.data)
    }

    return () => {
      socketRef.current = null
      socket.close()
    }
  }, [pushLog])

  // --- Auto-scroll the terminal as fresh telemetry arrives ---------------
  useEffect(() => {
    const terminal = terminalRef.current
    if (terminal) {
      terminal.scrollTop = terminal.scrollHeight
    }
  }, [logs])

  // --- Shared POST helper for the control buttons ------------------------
  const postCommand = useCallback(
    async (path, body, label) => {
      setPending(label)
      pushLog('system', `→ ${label} dispatched...`)
      try {
        const response = await fetch(`${SERVER_HTTP}${path}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: body ? JSON.stringify(body) : undefined,
        })
        const data = await response.json().catch(() => ({}))
        if (!response.ok) {
          throw new Error(data.status || `HTTP ${response.status}`)
        }
        pushLog('success', `✔ ${label}: ${data.status ?? 'acknowledged'}`)
      } catch (err) {
        pushLog('error', `✖ ${label} failed: ${err.message}`)
      } finally {
        setPending(null)
      }
    },
    [pushLog],
  )

  const handleTrigger = () =>
    postCommand('/trigger', INCIDENT_PAYLOAD, 'Trigger Incident')

  const handleReset = () => postCommand('/reset', null, 'Reset Environment')

  const statusLabel =
    connection === 'open'
      ? 'LINK ONLINE'
      : connection === 'connecting'
        ? 'LINKING'
        : 'LINK OFFLINE'

  return (
    <div className="mission-control">
      <header className="mc-header">
        <div className="mc-brand">
          <span className="mc-badge" aria-hidden="true">◤◢</span>
          <div className="mc-brand-text">
            <h1 className="mc-title">SentrySleuth Autonomous Engine</h1>
            <p className="mc-subtitle">
              Autonomous incident triage · live commit &amp; patch telemetry
            </p>
          </div>
        </div>
        <div className={`mc-link mc-link--${connection}`} role="status">
          <span className="mc-link-dot" aria-hidden="true" />
          {statusLabel}
        </div>
      </header>

      <section className="mc-panel" aria-label="Controls">
        <div className="mc-panel-head">
          <h2 className="mc-panel-title">Controls</h2>
          <span className="mc-panel-tag">operator console</span>
        </div>
        <div className="mc-controls">
          <button
            type="button"
            className="mc-btn mc-btn--danger"
            onClick={handleTrigger}
            disabled={pending !== null}
          >
            <span className="mc-btn-glyph" aria-hidden="true">⚠</span>
            Trigger Incident
          </button>
          <button
            type="button"
            className="mc-btn mc-btn--ghost"
            onClick={handleReset}
            disabled={pending !== null}
          >
            <span className="mc-btn-glyph" aria-hidden="true">↺</span>
            Reset Environment
          </button>
        </div>
        <p className="mc-hint">
          POST /trigger → <code>{JSON.stringify(INCIDENT_PAYLOAD)}</code>
          &nbsp;·&nbsp; POST /reset → git checkout .
        </p>
      </section>

      <section className="mc-panel mc-panel--terminal" aria-label="Live Telemetry">
        <div className="mc-panel-head">
          <h2 className="mc-panel-title">Live Telemetry Terminal</h2>
          <span className="mc-panel-tag">{logs.length} events</span>
        </div>
        <div className="mc-terminal" ref={terminalRef}>
          {logs.length === 0 ? (
            <div className="mc-placeholder">
              awaiting telemetry stream<span className="mc-cursor">_</span>
            </div>
          ) : (
            logs.map((log) => (
              <div key={log.id} className={`log-line log-line--${log.type}`}>
                <span className="log-time">{log.time}</span>
                <span className="log-tag">[{log.type}]</span>
                <span className="log-message">{log.message}</span>
              </div>
            ))
          )}
        </div>
      </section>
    </div>
  )
}

export default App
```

