import { useCallback, useEffect, useRef, useState } from 'react'
import './App.css'

const SERVER_HTTP = 'http://localhost:3001'
const SERVER_WS = 'ws://localhost:3001/stream'

// Payload expected by the Fastify POST /trigger endpoint
const INCIDENT_PAYLOAD = {
  errorType: 'TypeError',
  file: 'src/cart.js',
  line: 3,
}

// Message types the terminal knows how to color-code
const KNOWN_LEVELS = ['alert', 'error', 'success', 'info']

function resolveLevel(type) {
  return KNOWN_LEVELS.includes(type) ? type : 'system'
}

function App() {
  const [logs, setLogs] = useState([])
  const [linkState, setLinkState] = useState('connecting')
  const [pending, setPending] = useState(null)

  const terminalRef = useRef(null)
  const idRef = useRef(0)

  const pushLog = useCallback((type, message) => {
    setLogs((prev) => [
      ...prev,
      {
        id: (idRef.current += 1),
        level: resolveLevel(type),
        message,
        time: new Date().toLocaleTimeString('en-GB', { hour12: false }),
      },
    ])
  }, [])

  // Live telemetry: hold a WebSocket open to the autonomous engine
  useEffect(() => {
    let socket
    try {
      socket = new WebSocket(SERVER_WS)
    } catch (err) {
      pushLog('error', `Unable to open telemetry socket: ${err.message}`)
      setLinkState('closed')
      return undefined
    }

    socket.onopen = () => setLinkState('open')
    socket.onclose = () => setLinkState('closed')
    socket.onerror = () => setLinkState('error')

    socket.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data)
        pushLog(payload?.type, payload?.message ?? String(event.data))
      } catch {
        pushLog('info', String(event.data))
      }
    }

    return () => socket.close()
  }, [pushLog])

  // Auto-scroll the terminal whenever a new line lands
  useEffect(() => {
    const terminal = terminalRef.current
    if (terminal) {
      terminal.scrollTop = terminal.scrollHeight
    }
  }, [logs])

  // Fire a command at the backend and mirror the result into the terminal
  const runCommand = useCallback(
    async (key, label, path, body) => {
      setPending(key)
      pushLog('system', `→ ${label} dispatched...`)
      try {
        const response = await fetch(`${SERVER_HTTP}${path}`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: body ? JSON.stringify(body) : undefined,
        })
        const data = await response.json().catch(() => ({}))
        if (!response.ok) {
          throw new Error(data.error || data.status || `HTTP ${response.status}`)
        }
        pushLog('success', `✔ ${label}: ${data.status ?? 'acknowledged'}`)
      } catch (err) {
        pushLog('error', `✖ ${label} failed: ${err.message}`)
      } finally {
        setPending(null)
      }
    },
    [pushLog],
  )

  const handleTrigger = () =>
    runCommand('trigger', 'Trigger Incident', '/trigger', INCIDENT_PAYLOAD)

  const handleReset = () =>
    runCommand('reset', 'Reset Environment', '/reset', null)

  const linkLabel =
    linkState === 'open'
      ? 'LINK ONLINE'
      : linkState === 'connecting'
        ? 'LINKING'
        : 'LINK OFFLINE'

  return (
    <div className="mission-control">
      <header className="mc-header">
        <div className="mc-brand">
          <span className="mc-badge" aria-hidden="true">
            ◤◢
          </span>
          <div>
            <h1 className="mc-title">SentrySleuth Autonomous Engine</h1>
            <p className="mc-subtitle">
              autonomous incident triage · live commit &amp; patch telemetry
            </p>
          </div>
        </div>
        <div className={`mc-link mc-link--${linkState}`} role="status">
          <span className="mc-link-dot" aria-hidden="true" />
          {linkLabel}
        </div>
      </header>

      <section className="mc-panel" aria-label="Controls">
        <div className="mc-panel-head">
          <h2 className="mc-panel-title">Controls</h2>
          <span className="mc-panel-tag">operator console</span>
        </div>
        <div className="mc-controls">
          <button
            type="button"
            className="mc-btn mc-btn--danger"
            onClick={handleTrigger}
            disabled={pending === 'trigger'}
          >
            <span className="mc-btn-glyph" aria-hidden="true">
              ⚠
            </span>
            Trigger Incident
          </button>
          <button
            type="button"
            className="mc-btn mc-btn--ghost"
            onClick={handleReset}
            disabled={pending === 'reset'}
          >
            <span className="mc-btn-glyph" aria-hidden="true">
              ↺
            </span>
            Reset Environment
          </button>
        </div>
        <p className="mc-hint">
          POST <code>/trigger</code> {JSON.stringify(INCIDENT_PAYLOAD)} · POST{' '}
          <code>/reset</code> restores the broken repo
        </p>
      </section>

      <section
        className="mc-panel mc-panel--terminal"
        aria-label="Live Telemetry Terminal"
      >
        <div className="mc-panel-head">
          <h2 className="mc-panel-title">Live Telemetry Terminal</h2>
          <span className="mc-panel-tag">{logs.length} events</span>
        </div>
        <div className="mc-terminal" ref={terminalRef}>
          {logs.length === 0 ? (
            <div className="mc-placeholder">
              awaiting telemetry stream
              <span className="mc-cursor">_</span>
            </div>
          ) : (
            logs.map((log) => (
              <div key={log.id} className={`log-line log-line--${log.level}`}>
                <span className="log-time">{log.time}</span>
                <span className="log-tag">[{log.level}]</span>
                <span className="log-message">{log.message}</span>
              </div>
            ))
          )}
        </div>
      </section>
    </div>
  )
}

export default App

