/* ============================================================
   SentrySleuth — Mission Control Dashboard
   Dark, monospace "operator console" styling (plain CSS, no Tailwind)
   ============================================================ */

:root {
  --mc-bg: #05070a;
  --mc-panel: rgba(12, 20, 34, 0.9);
  --mc-border: #1b2c46;
  --mc-border-soft: #14213a;
  --mc-text: #c6d5e8;
  --mc-text-dim: #6f88a8;
  --mc-green: #37f499;
  --mc-cyan: #38e1ff;
  --mc-red: #ff4d5e;
  --mc-blue: #5aa2ff;
  --mc-amber: #ffb454;
  --mc-mono: 'JetBrains Mono', 'SFMono-Regular', ui-monospace, Menlo, Consolas,
    'Liberation Mono', monospace;
}

/* Give the whole app a dark canvas regardless of system colour scheme */
body {
  background: var(--mc-bg);
}

/* Let the dashboard span the full viewport instead of the demo column */
#root {
  width: 100%;
  max-width: 100%;
  border-inline: none;
}

.mission-control {
  box-sizing: border-box;
  min-height: 100svh;
  padding: 28px clamp(16px, 4vw, 48px) 40px;
  display: flex;
  flex-direction: column;
  gap: 22px;
  text-align: left;
  font-family: var(--mc-mono);
  color: var(--mc-text);
  background:
    radial-gradient(
      1100px 480px at 15% -10%,
      rgba(56, 225, 255, 0.12),
      transparent 60%
    ),
    radial-gradient(
      900px 420px at 100% 0%,
      rgba(55, 244, 153, 0.1),
      transparent 55%
    ),
    linear-gradient(180deg, #070b14 0%, #05070a 100%);
}

/* ---------- Header ---------- */
.mc-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 20px;
  padding-bottom: 18px;
  border-bottom: 1px solid var(--mc-border-soft);
}

.mc-brand {
  display: flex;
  align-items: center;
  gap: 16px;
}

.mc-badge {
  font-size: 26px;
  line-height: 1;
  color: var(--mc-green);
  text-shadow: 0 0 14px rgba(55, 244, 153, 0.7);
}

.mc-title {
  margin: 0;
  font-family: var(--mc-mono);
  font-size: clamp(20px, 2.6vw, 30px);
  font-weight: 600;
  letter-spacing: 0.02em;
  color: #eaf3ff;
  text-shadow: 0 0 22px rgba(56, 225, 255, 0.28);
}

.mc-subtitle {
  margin: 6px 0 0;
  font-size: 12.5px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mc-text-dim);
}

.mc-link {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 14px;
  font-size: 12px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  border: 1px solid var(--mc-border);
  border-radius: 999px;
  background: rgba(10, 18, 30, 0.7);
  color: var(--mc-text-dim);
}

.mc-link-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--mc-text-dim);
}

.mc-link--open {
  color: var(--mc-green);
  border-color: rgba(55, 244, 153, 0.45);
  box-shadow: 0 0 18px rgba(55, 244, 153, 0.18);
}

.mc-link--open .mc-link-dot {
  background: var(--mc-green);
  box-shadow: 0 0 10px var(--mc-green);
  animation: mc-pulse 1.6s ease-in-out infinite;
}

.mc-link--connecting {
  color: var(--mc-amber);
  border-color: rgba(255, 180, 84, 0.4);
}

.mc-link--connecting .mc-link-dot {
  background: var(--mc-amber);
  animation: mc-pulse 1s ease-in-out infinite;
}

.mc-link--closed,
.mc-link--error {
  color: var(--mc-red);
  border-color: rgba(255, 77, 94, 0.45);
}

.mc-link--closed .mc-link-dot,
.mc-link--error .mc-link-dot {
  background: var(--mc-red);
}

/* ---------- Panels ---------- */
.mc-panel {
  border: 1px solid var(--mc-border);
  border-radius: 14px;
  background: var(--mc-panel);
  box-shadow: 0 18px 40px -28px rgba(0, 0, 0, 0.9);
  padding: 18px 20px 20px;
}

.mc-panel--terminal {
  display: flex;
  flex-direction: column;
  gap: 14px;
  flex: 1;
}

.mc-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.mc-panel-title {
  margin: 0;
  font-family: var(--mc-mono);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #dbe8f7;
}

.mc-panel-title::before {
  content: '// ';
  color: var(--mc-green);
}

.mc-panel-tag {
  font-size: 11px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--mc-text-dim);
}

/* __MC_CSS_TAIL__ */

