input.new_text:
/* ---------- Controls ---------- */
.mc-controls {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.mc-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 12px 22px;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #eaf3ff;
  background: rgba(20, 32, 50, 0.85);
  border: 1px solid var(--mc-border);
  border-radius: 10px;
  cursor: pointer;
  transition:
    transform 0.15s ease,
    box-shadow 0.2s ease,
    border-color 0.2s ease,
    background 0.2s ease;
}

.mc-btn:hover:not(:disabled) {
  transform: translateY(-1px);
  border-color: var(--mc-cyan);
  box-shadow: 0 0 22px rgba(56, 225, 255, 0.22);
}

.mc-btn:active:not(:disabled) {
  transform: translateY(0);
}

.mc-btn:focus-visible {
  outline: 2px solid var(--mc-cyan);
  outline-offset: 2px;
}

.mc-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.mc-btn--danger {
  color: #ffe7ea;
  background: linear-gradient(180deg, rgba(120, 22, 34, 0.9), rgba(70, 12, 20, 0.9));
  border-color: rgba(255, 77, 94, 0.55);
}

.mc-btn--danger:hover:not(:disabled) {
  border-color: var(--mc-red);
  box-shadow: 0 0 24px rgba(255, 77, 94, 0.35);
}

.mc-btn--ghost {
  color: var(--mc-cyan);
  border-color: rgba(56, 225, 255, 0.35);
}

.mc-btn-glyph {
  font-size: 15px;
  line-height: 1;
}

.mc-hint {
  margin: 16px 0 0;
  font-size: 12px;
  color: var(--mc-text-dim);
}

.mc-hint code {
  display: inline;
  font-family: var(--mc-mono);
  font-size: 11.5px;
  color: var(--mc-green);
  background: rgba(55, 244, 153, 0.08);
  border: 1px solid rgba(55, 244, 153, 0.18);
  border-radius: 5px;
  padding: 2px 6px;
}

/* ---------- Live Telemetry Terminal ---------- */
.mc-terminal {
  flex: 1;
  min-height: 320px;
  max-height: 56vh;
  overflow-y: auto;
  padding: 16px 18px;
  background: #04060a;
  border: 1px solid #10203a;
  border-radius: 10px;
  font-size: 13.5px;
  line-height: 1.65;
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.85);
  scrollbar-width: thin;
  scrollbar-color: #1d3557 #04060a;
}

.mc-terminal::-webkit-scrollbar {
  width: 10px;
}

.mc-terminal::-webkit-scrollbar-track {
  background: #04060a;
}

.mc-terminal::-webkit-scrollbar-thumb {
  background: #1d3557;
  border-radius: 6px;
}

.log-line {
  display: flex;
  gap: 10px;
  white-space: pre-wrap;
  word-break: break-word;
  animation: mc-fade-in 0.28s ease;
}

.log-time {
  flex: none;
  color: #40597a;
}

.log-tag {
  flex: none;
  text-transform: uppercase;
  opacity: 0.85;
}

.log-message {
  color: inherit;
}

/* Type-based colour coding */
.log-line--alert {
  color: var(--mc-red);
}

.log-line--error {
  color: #ff7a6b;
}

.log-line--success {
  color: var(--mc-green);
}

.log-line--info {
  color: var(--mc-blue);
}

.log-line--system {
  color: var(--mc-amber);
}

.log-line--alert .log-tag {
  color: var(--mc-red);
}

.log-line--error .log-tag {
  color: #ff7a6b;
}

.log-line--success .log-tag {
  color: var(--mc-green);
}

.log-line--info .log-tag {
  color: var(--mc-blue);
}

.mc-placeholder {
  color: var(--mc-text-dim);
  letter-spacing: 0.04em;
}

.mc-cursor {
  margin-left: 2px;
  color: var(--mc-green);
  animation: mc-blink 1.05s step-end infinite;
}

/* ---------- Animations ---------- */
@keyframes mc-pulse {
  0%,
  100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.8);
  }
}

@keyframes mc-blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}

@keyframes mc-fade-in {
  from {
    opacity: 0;
    transform: translateY(3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ---------- Responsive ---------- */
@media (max-width: 640px) {
  .mc-header {
    flex-direction: column;
    align-items: flex-start;
  }

  .mc-btn {
    flex: 1 1 100%;
    justify-content: center;
  }

  .log-line {
    flex-wrap: wrap;
  }
}

