// Resolve a user-supplied path and guarantee it stays inside the workspace.
function resolveInsideWorkspace(workspacePath, filePath) {
    const root = path.resolve(workspacePath);
    const target = path.resolve(root, filePath);
    if (target !== root && !target.startsWith(root + path.sep)) {
        throw new Error(`Blocked path outside workspace: ${filePath}`);
    }
    return target;
}

export function runGitBlame(workspacePath, filePath, lineNumber) {
    try {
        const targetDir = path.resolve(workspacePath);
        const targetFile = resolveInsideWorkspace(workspacePath, filePath);
        const output = execSync(
            `git blame -L ${lineNumber},${lineNumber} -- "${targetFile}"`,
            { cwd: targetDir, encoding: 'utf-8' }
        );
        return output.trim();
    } catch (error) {
        return `Error running git blame: ${error.message}`;
    }
}
