import Fastify from 'fastify';
import websocket from '@fastify/websocket';
import cors from '@fastify/cors';
import multipart from '@fastify/multipart';
import AdmZip from 'adm-zip';
import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { runSentrySleuth } from './agent/index.js';

// ---------------------------------------------------------------------------
// Absolute path determinism: resolve the workspaces root relative to THIS file
// ---------------------------------------------------------------------------
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WORKSPACES_ROOT = path.resolve(__dirname, 'workspaces');

// Make sure the staging area exists before we ever try to write into it
fs.mkdirSync(WORKSPACES_ROOT, { recursive: true });

const fastify = Fastify({ logger: false });

await fastify.register(cors, { origin: '*' });
await fastify.register(websocket);
await fastify.register(multipart, {
    limits: { fileSize: 100 * 1024 * 1024 } // 100 MB archives
});

const connectedClients = new Set();

// --- Live telemetry channel -------------------------------------------------
fastify.register(async function (fastify) {
    fastify.get('/stream', { websocket: true }, (connection, req) => {
        connectedClients.add(connection.socket);
        connection.socket.send(JSON.stringify({ type: 'info', message: '🟢 Connected to SentrySleuth Server!' }));

        connection.socket.on('close', () => {
            connectedClients.delete(connection.socket);
        });
    });
});

function broadcast(messagePayload) {
    for (const client of connectedClients) {
        client.send(JSON.stringify(messagePayload));
    }
}

// --- Helpers ----------------------------------------------------------------
function newWorkspaceId() {
    return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function assertSafeWorkspaceId(workspaceId) {
    if (!/^[A-Za-z0-9_-]+$/.test(workspaceId)) {
        throw new Error('Invalid workspaceId');
    }
    return workspaceId;
}

function workspaceDirFor(workspaceId) {
    return path.join(WORKSPACES_ROOT, assertSafeWorkspaceId(workspaceId));
}

// --- Ingest: ZIP upload -----------------------------------------------------
fastify.post('/ingest/zip', async (request, reply) => {
    let data;
    try {
        data = await request.file();
    } catch (error) {
        return reply.code(400).send({ status: 'failed', error: `Expected a multipart upload: ${error.message}` });
    }

    if (!data) {
        return reply.code(400).send({ status: 'failed', error: 'No file was uploaded.' });
    }

    const workspaceId = newWorkspaceId();
    const workspacePath = path.join(WORKSPACES_ROOT, workspaceId);

    try {
        const buffer = await data.toBuffer();
        fs.mkdirSync(workspacePath, { recursive: true });

        const zip = new AdmZip(buffer);
        const entries = zip.getEntries();
        if (entries.length === 0) {
            throw new Error('The uploaded archive is empty.');
        }

        // Guard against zip-slip: every entry must land inside workspacePath
        for (const entry of entries) {
            const target = path.join(workspacePath, entry.entryName);
            if (target !== workspacePath && !target.startsWith(workspacePath + path.sep)) {
                throw new Error(`Blocked unsafe entry in archive: ${entry.entryName}`);
            }
            if (entry.isDirectory) {
                fs.mkdirSync(target, { recursive: true });
            } else {
                fs.mkdirSync(path.dirname(target), { recursive: true });
                fs.writeFileSync(target, entry.getData());
            }
        }
    } catch (error) {
        broadcast({ type: 'error', message: `❌ ZIP ingest failed: ${error.message}` });
        return reply.code(400).send({ status: 'failed', error: error.message });
    }

    broadcast({ type: 'info', message: `📦 Workspace ${workspaceId} staged from archive.` });
    return { workspaceId, workspacePath };
});

// --- Ingest: public Git clone ----------------------------------------------
fastify.post('/ingest/git', async (request, reply) => {
    const { repoUrl } = request.body ?? {};

    if (!repoUrl || typeof repoUrl !== 'string') {
        return reply.code(400).send({ status: 'failed', error: 'repoUrl is required.' });
    }

    const workspaceId = newWorkspaceId();
    const workspacePath = path.join(WORKSPACES_ROOT, workspaceId);

    try {
        // Clone into a fresh workspace directory (git creates it)
        execSync(`git clone --depth 1 ${JSON.stringify(repoUrl)} ${JSON.stringify(workspacePath)}`, {
            stdio: 'pipe',
            encoding: 'utf-8'
        });
    } catch (error) {
        // Clean up a half-created workspace so the staging area stays tidy
        try {
            fs.rmSync(workspacePath, { recursive: true, force: true });
        } catch { /* ignore cleanup errors */ }

        const detail = error.stderr ? String(error.stderr).trim() : error.message;
        broadcast({ type: 'error', message: `❌ Git ingest failed: ${detail}` });
        return reply.code(400).send({ status: 'failed', error: detail });
    }

    broadcast({ type: 'info', message: `📦 Workspace ${workspaceId} staged from ${repoUrl}.` });
    return { workspaceId, workspacePath };
});

// --- Trigger the agent inside a workspace ----------------------------------
fastify.post('/trigger', async (request, reply) => {
    const { workspacePath, file, line, errorType } = request.body ?? {};

    if (!workspacePath) {
        return reply.code(400).send({ status: 'failed', error: 'workspacePath is required.' });
    }

    broadcast({ type: 'alert', message: `🚨 INCIDENT TRIGGERED: ${file} (Line ${line})` });

    runSentrySleuth({ workspacePath, file, line, errorType })
        .then(() => broadcast({ type: 'success', message: '✅ Agent finished the mission.' }))
        .catch(() => broadcast({ type: 'error', message: '❌ Agent failed.' }));

    return { status: 'Investigating...' };
});

// --- Download the patched workspace as a zip --------------------------------
fastify.get('/download/:workspaceId', async (request, reply) => {
    const { workspaceId } = request.params;

    let workspacePath;
    try {
        workspacePath = workspaceDirFor(workspaceId);
    } catch (error) {
        return reply.code(400).send({ status: 'failed', error: error.message });
    }

    if (!fs.existsSync(workspacePath)) {
        return reply.code(404).send({ status: 'failed', error: 'Workspace not found.' });
    }

    try {
        const zip = new AdmZip();
        zip.addLocalFolder(workspacePath);
        const buffer = zip.toBuffer();

        return reply
            .header('Content-Type', 'application/zip')
            .header('Content-Disposition', `attachment; filename="sentrysleuth-${workspaceId}.zip"`)
            .send(buffer);
    } catch (error) {
        return reply.code(500).send({ status: 'failed', error: error.message });
    }
});

// --- Boot -------------------------------------------------------------------
try {
    await fastify.listen({ port: 3001 });
    console.log('🚀 SentrySleuth Backend is LIVE at http://localhost:3001');
    console.log(`📂 Workspaces root: ${WORKSPACES_ROOT}`);
} catch (err) {
    console.error(err);
    process.exit(1);
}
