import path from 'path';

/**
 * Resolve a caller-supplied path and guarantee it stays strictly inside the
 * workspace it belongs to. Every MCP tool is sandboxed to its workspace and
 * this is the single choke-point that enforces that rule.
 */
export function resolveInsideWorkspace(workspacePath, filePath) {
    if (!workspacePath) {
        throw new Error('workspacePath is required');
    }
    const root = path.resolve(workspacePath);
    const target = path.resolve(root, filePath);
    if (target !== root && !target.startsWith(root + path.sep)) {
        throw new Error(`Blocked path outside workspace: ${filePath}`);
    }
    return target;
}
