import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";

import { runGitBlame } from "./tools/gitBlame.js";
import { readSourceFile } from "./tools/sourceReader.js";
import { patchSourceFile } from "./tools/sourcePatcher.js";
import { runTests } from "./tools/testRunner.js";

// Initialize the MCP server
const server = new McpServer({
  name: "SentrySleuth-Tools",
  version: "1.0.0"
});

// Every tool is sandboxed to an explicit workspace directory.
const workspacePathSchema = z
  .string()
  .describe("Absolute path to the isolated workspace this tool must operate strictly inside");

// Tool 1: Git Blame Inspector
server.tool(
  "git_blame_inspector",
  "Inspects git history for a specific line of code inside a workspace",
  {
    workspacePath: workspacePathSchema,
    filePath: z.string().describe("Path to the file, relative to the workspace root"),
    lineNumber: z.number().describe("Line number to inspect")
  },
  async ({ workspacePath, filePath, lineNumber }) => {
    return { content: [{ type: "text", text: runGitBlame(workspacePath, filePath, lineNumber) }] };
  }
);

// Tool 2: Source Reader
server.tool(
  "source_reader",
  "Reads the content of a source file inside a workspace",
  {
    workspacePath: workspacePathSchema,
    filePath: z.string().describe("Path to the file to read, relative to the workspace root")
  },
  async ({ workspacePath, filePath }) => {
    return { content: [{ type: "text", text: readSourceFile(workspacePath, filePath) }] };
  }
);

// Tool 3: Source Patcher
server.tool(
  "source_patcher",
  "Overwrites a file with new patched content inside a workspace",
  {
    workspacePath: workspacePathSchema,
    filePath: z.string().describe("Path to the file to patch, relative to the workspace root"),
    newContent: z.string().describe("The complete new file content")
  },
  async ({ workspacePath, filePath, newContent }) => {
    return { content: [{ type: "text", text: patchSourceFile(workspacePath, filePath, newContent) }] };
  }
);

// Tool 4: Sandbox Test Runner
server.tool(
  "sandbox_test_runner",
  "Runs the workspace test suite to verify code changes",
  {
    workspacePath: workspacePathSchema
  },
  async ({ workspacePath }) => {
    const result = runTests(workspacePath);
    const statusText = result.exitCode === 0 ? "SUCCESS" : "FAILED";
    const fullOutput = `Status: ${statusText}\nExit Code: ${result.exitCode}\n\nOutput:\n${result.output}`;
    return { content: [{ type: "text", text: fullOutput }] };
  }
);

// Start the server using standard input/output
async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

main();
