        const zip = new AdmZip();
        zip.addLocalFolder(workspacePath);
        const buffer = zip.toBuffer();

        return reply
            .header('Content-Type', 'application/zip')
            .header('Content-Disposition', `attachment; filename="sentrysleuth-${request.params.workspaceId}.zip"`)
            .send(buffer);
    } catch (error) {
        broadcast({ type: 'error', message: `❌ Download failed: ${error.message}` });
        return reply.code(500).send({ status: 'failed', error: error.message });
    }
