            <label className="mc-field mc-field--wide">
              <span className="mc-label">Public Git Repo URL</span>
              <input
                type="url"
                className="mc-input"
                placeholder="https://github.com/user/repo.git"
                value={repoUrl}
                onChange={(e) => setRepoUrl(e.target.value)}
              />
            </label>
          )}

          <label className="mc-field">
            <span className="mc-label">Target File Path</span>
            <input
              type="text"
              className="mc-input"
              placeholder="src/cart.js"
              value={file}
              onChange={(e) => setFile(e.target.value)}
            />
          </label>

          <label className="mc-field mc-field--narrow">
            <span className="mc-label">Line Number</span>
            <input
              type="number"
              min="1"
              className="mc-input"
              placeholder="3"
              value={line}
              onChange={(e) => setLine(e.target.value)}
            />
          </label>

          <label className="mc-field mc-field--wide">
            <span className="mc-label">Error Message</span>
            <input
              type="text"
