import { spawnSync } from 'child_process';
import path from 'path';
import { resolveInsideWorkspace } from './workspacePath.js';

const ALLOWED_BINARIES = new Set(['pytest', 'python', 'python3']);
// Disallow shell metacharacters entirely (we never use a shell, but reject just in case)
const SHELL_METACHARS = /[;&|`$><\n\r(){}[\]*?!~#]/;

export function runPythonTests(workspacePath, testCommand = 'pytest') {
    try {
        // Resolve (and verify) the workspace root we are allowed to operate in
        const cwd = resolveInsideWorkspace(workspacePath, '.');

        const raw = (testCommand && String(testCommand).trim()) || 'pytest';
        if (SHELL_METACHARS.test(raw)) {
            return { ok: false, exitCode: 1, stdout: '', stderr: `Rejected unsafe test command: ${raw}` };
        }

        const tokens = raw.split(/\s+/).filter(Boolean);
        const [bin, ...args] = tokens;

        if (!ALLOWED_BINARIES.has(bin)) {
            return { ok: false, exitCode: 1, stdout: '', stderr: `Unsupported python runner: ${bin}. Allowed: pytest, python, python3` };
        }

        // If a python script path is referenced, force it inside the workspace
        const safeArgs = args.map((arg) => {
            if (arg.endsWith('.py')) {
                // resolve relative to the workspace and confirm containment
                return resolveInsideWorkspace(workspacePath, arg);
            }
            return arg;
        });

        const result = spawnSync(bin, safeArgs, {
            cwd,
            encoding: 'utf-8',
            env: { ...process.env, PYTHONUNBUFFERED: '1', PYTHONDONTWRITEBYTECODE: '1' },
            timeout: 5 * 60 * 1000
        });

        const stdout = result.stdout || '';
        const stderr = result.stderr || '';
        const exitCode = typeof result.status === 'number' ? result.status : 1;
        const spawnError = result.error ? `\n[spawn error] ${result.error.message}` : '';

        return {
            ok: exitCode === 0 && !result.error,
            exitCode,
            stdout,
            stderr: stderr + spawnError,
            command: `${bin} ${safeArgs.join(' ')}`.trim()
        };
    } catch (error) {
        return { ok: false, exitCode: 1, stdout: '', stderr: `Error running python tests: ${error.message}` };
    }
}
```

