import { spawnSync } from 'child_process';
import path from 'path';
import { resolveInsideWorkspace } from './workspacePath.js';

// Only these interpreters/tools may be invoked as the python test runner.
const ALLOWED_BINARIES = new Set(['pytest', 'python', 'python3']);

// We never use a shell, but reject metacharacters defensively as well.
const SHELL_METACHARS = /[;&|`$><\n\r(){}[\]*?!~#]/;

// Turn a raw command string into a [bin, ...args] pair, forcing every path
// argument to stay strictly inside the workspace.
function buildInvocation(workspacePath, command) {
    const tokens = String(command).trim().split(/\s+/).filter(Boolean);
    const bin = tokens[0];
    const rawArgs = tokens.slice(1);

    const args = rawArgs.map((arg, index) => {
        if (arg.startsWith('-')) return arg;                         // flags
        if (index > 0 && rawArgs[index - 1] === '-m') return arg;    // module name after -m
        return resolveInsideWorkspace(workspacePath, arg);           // a path: keep it sandboxed
    });

    return { bin, args };
}

/**
 * Safely run a Python test command strictly inside `workspacePath`.
 * Captures stdout, stderr and the exit code and NEVER throws.
 */
export function runPythonTests(workspacePath, testCommand = 'pytest') {
    try {
        // Resolving '.' proves the workspace exists and is usable.
        const cwd = resolveInsideWorkspace(workspacePath, '.');

        const command = (testCommand && String(testCommand).trim()) || 'pytest';
        if (SHELL_METACHARS.test(command)) {
            return { exitCode: 1, stdout: '', stderr: `Rejected unsafe test command: ${command}`, command };
        }

        const { bin, args } = buildInvocation(workspacePath, command);
        if (!ALLOWED_BINARIES.has(bin)) {
            return {
                exitCode: 1,
                stdout: '',
                stderr: `Unsupported python runner "${bin}". Allowed: pytest, python, python3.`,
                command
            };
        }

        const spawned = spawnSync(bin, args, {
            cwd,
            encoding: 'utf-8',
            timeout: 5 * 60 * 1000,
            env: { ...process.env, PYTHONUNBUFFERED: '1', PYTHONDONTWRITEBYTECODE: '1' }
        });

        const stdout = spawned.stdout || '';
        const stderr = spawned.stderr || '';
        const exitCode = typeof spawned.status === 'number' ? spawned.status : 1;
        const spawnError = spawned.error ? `\n[spawn error] ${spawned.error.message}` : '';

        return { exitCode, stdout, stderr: `${stderr}${spawnError}`, command: `${bin} ${args.join(' ')}`.trim() };
    } catch (error) {
        return { exitCode: 1, stdout: '', stderr: `Error running python tests: ${error.message}`, command: testCommand };
    }
}
