function buildDiff(original, proposed) {
  const a = String(original ?? '').split('\n');
  const b = String(proposed ?? '').split('\n');
  const lines = [];
  const n = Math.max(a.length, b.length);
  for (let i = 0; i < n && lines.length < 400; i++) {
    const oldLine = a[i];
    const newLine = b[i];
    if (oldLine === newLine) {
      lines.push(`  ${oldLine ?? ''}`);
    } else {
      if (oldLine !== undefined) lines.push(`- ${oldLine}`);
      if (newLine !== undefined) lines.push(`+ ${newLine}`);
    }
  }
  if (lines.length >= 400) lines.push('... [diff truncated] ...');
  return lines.join('\n');
}
