const ALLOWED_BINARIES = new Set(['pytest', 'python', 'python3']);

// We never spawn through a shell, but reject metacharacters defensively anyway.
const SHELL_METACHARS = /[;&|`$><\n\r(){}[\]*?!~#]/;

const DEFAULT_COMMAND = 'pytest';
const TIMEOUT_MS = 5 * 60 * 1000;

/**
 * Turn a raw command string into [bin, ...args], forcing every *path* argument
 * to stay strictly inside the workspace. Flags and `-m <module>` names are kept
 * verbatim; anything that looks like a path is funnelled through
 * `resolveInsideWorkspace()` (which throws when it escapes the workspace).
 */
function buildInvocation(workspacePath, command) {
    const tokens = String(command).trim().split(/\s+/).filter(Boolean);
    const bin = tokens[0];
    const rawArgs = tokens.slice(1);

    const args = rawArgs.map((arg, index) => {
        if (arg.startsWith('-')) return arg; // flag, e.g. -m, -q, -v
        if (index > 0 && rawArgs[index - 1] === '-m') return arg; // module name after -m
        return resolveInsideWorkspace(workspacePath, arg); // a path -> sandbox it
    });

    return { bin, args };
}

/**
