 * strictly inside `workspacePath`. Captures stdout, stderr and the exit code and
 * NEVER throws: any failure is returned as a structured result.
 */
export function runPythonTests(workspacePath, testCommand = DEFAULT_COMMAND) {
    try {
        // Resolving '.' validates the workspace and pins us to its absolute root.
        const cwd = resolveInsideWorkspace(workspacePath, '.');

        const command = (testCommand && String(testCommand).trim()) || DEFAULT_COMMAND;

        if (SHELL_METACHARS.test(command)) {
            return {
                exitCode: 1,
                stdout: '',
                stderr: `Rejected unsafe test command: ${command}`,
                command
