        // `status` is null when the process failed to spawn (e.g. ENOENT) or timed out.
        const exitCode = typeof spawned.status === 'number' ? spawned.status : 1;
        const spawnError = spawned.error ? `\n[spawn error] ${spawned.error.message}` : '';

        return {
            exitCode,
            stdout,
            stderr: `${stderr}${spawnError}`,
            command: `${bin} ${args.join(' ')}`.trim()
        };
    } catch (error) {
        return {
            exitCode: 1,
            stdout: '',
            stderr: `Error running python tests: ${error.message}`,
            command: testCommand
        };
    }
}

