/**
 * Autonomous two-agent remediation loop.
 *
 *  Agent A (Lead Investigator)  -> inspects + drafts a patch (never writes)
 *  Agent B (Senior QA Reviewer) -> approves or rejects with critiques
 *  On approval -> patch written via source_patcher, then the runtime's test runner.
 */
export async function runSentrySleuth(crashDetails, emitEvent = () => {}) {
    const {
        workspacePath,
        file,
        line,
        errorType,
        mode = 'reliability',
        runtime = 'node',
        testCommand
    } = crashDetails || {};

    if (!workspacePath) throw new Error('workspacePath is required');

    const emit = makeEmitter(emitEvent);
    const isSecurity = mode === 'security';
    const isPython = runtime === 'python';

    console.log(`🚨 SENTRY ALERT: ${errorType} in ${file} at line ${line} [${mode}/${runtime}]`);
    console.log(`📂 Active workspace: ${workspacePath}`);

    emit('investigator', `🔍 Agent A (Lead Investigator) dispatched — mode=${mode}, runtime=${runtime}`);
    emit('reviewer', `🧪 Agent B (Senior QA Reviewer) on standby.`);

    // Snapshot the pristine file so the workspace can be restored if nothing is approved.
    const originalSource = readSourceFile(workspacePath, file);
    const originalReadable = !/^Error reading file/.test(originalSource);

    const investigator = new Agent({
        name: 'SentrySleuth - Lead Investigator',
        providerId: PROVIDER_ID,
        modelId: MODEL_ID,
        apiKey: API_KEY,
        systemPrompt: investigatorSystemPrompt({ workspacePath, file, line, errorType, mode, runtime }),
        allowedTools: ['git_blame_inspector', 'source_reader']
    });

    const reviewer = new Agent({
        name: 'SentrySleuth - Senior QA Reviewer',
        providerId: PROVIDER_ID,
        modelId: MODEL_ID,
        apiKey: API_KEY,
        systemPrompt: reviewerSystemPrompt(),
        allowedTools: []
    });

    const initialTask = `Begin your investigation of ${file} (line ${line}) in workspace "${workspacePath}".`;

    let critiques = '';
    let lastProposal = null;

    for (let round = 1; round <= MAX_REVIEW_ROUNDS; round++) {
        // ----- Agent A: draft (or revise) the patch ---------------------------------
        const task = round === 1
            ? initialTask
            : `Agent B REJECTED your previous patch. Address EVERY critique below and resubmit the FULL file inside <proposed_patch file="${file}">...</proposed_patch>.\n\nREVIEWER CRITIQUES:\n${truncate(critiques)}`;

        emit('investigator', `📝 Agent A drafting a patch (round ${round}/${MAX_REVIEW_ROUNDS})...`);
        const aRun = await runAgent(investigator, task);

        if (!aRun.outputText) {
            emit('investigator', `⚠️ Agent A returned no output (status: ${aRun.status})${aRun.error ? `: ${aRun.error.message}` : ''}.`);
