import { Agent } from '@cline/sdk';
import { readSourceFile } from '../tools/sourceReader.js';
import { patchSourceFile } from '../tools/sourcePatcher.js';
import { runTests } from '../tools/testRunner.js';
import { runPythonTests } from '../tools/pythonRunner.js';

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
const PROVIDER_ID = 'anthropic'; // (or "openai" / "google")
const MODEL_ID = 'claude-3-5-sonnet-latest'; // (or "gpt-4o" / "gemini-1.5-pro")
const API_KEY = 'YOUR_API_KEY_HERE'; // <-- paste your real provider key here

const MAX_REVIEW_ROUNDS = 3;
const MAX_TEXT_CHARS = 20000;
const MAX_DIFF_LINES = 400;

// ---------------------------------------------------------------------------
// Small, self-contained helpers (none of these are allowed to throw)
// ---------------------------------------------------------------------------
function truncate(text, max = MAX_TEXT_CHARS) {
    const value = text == null ? '' : String(text);
    return value.length > max
        ? `${value.slice(0, max)}\n... [truncated ${value.length - max} chars]`
        : value;
}

function countLines(text) {
    return String(text || '').split('\n').length;
}

function firstLine(text) {
    return String(text || '')
        .split('\n')
        .map((line) => line.trim())
        .find(Boolean) || '';
}

// Emit a WebSocket event without ever letting telemetry break the run.
function makeEmitter(emitEvent) {
    return (type, message) => {
        try {
            if (typeof emitEvent === 'function') emitEvent({ type, message });
        } catch {
            /* ignore telemetry failures */
        }
    };
}

// Pull the full replacement file out of Agent A's response.
function extractProposedPatch(text) {
    if (!text) return null;

    const tagged = /<proposed_patch[^>]*>([\s\S]*?)<\/proposed_patch>/i.exec(text);
    if (tagged) return tagged[1].replace(/^\n+/, '').replace(/\n+$/, '');

    const fenced = /```[a-zA-Z0-9+#._-]*\n([\s\S]*?)```/.exec(text);
    if (fenced) return fenced[1].replace(/\n$/, '');

    return null;
}

// Line-by-line diff of the current file against the proposed replacement.
function buildDiff(original, proposed) {
    const before = String(original ?? '').split('\n');
    const after = String(proposed ?? '').split('\n');
    const lines = [];
    const width = Math.max(before.length, after.length);

    for (let i = 0; i < width && lines.length < MAX_DIFF_LINES; i++) {
        const oldLine = before[i];
        const newLine = after[i];
        if (oldLine === newLine) {
            lines.push(`  ${oldLine ?? ''}`);
        } else {
            if (oldLine !== undefined) lines.push(`- ${oldLine}`);
            if (newLine !== undefined) lines.push(`+ ${newLine}`);
        }
    }

    if (lines.length >= MAX_DIFF_LINES) lines.push('... [diff truncated] ...');
    return lines.join('\n');
}

// Parse Agent B's mandatory VERDICT line (with a tolerant fallback).
function parseVerdict(text) {
    const match = /VERDICT\s*[:\-]\s*(APPROVED|REJECTED)/i.exec(text || '');
    if (match) {
        const verdict = match[1].toUpperCase();
        return { approved: verdict === 'APPROVED', verdict };
    }

    const upper = String(text || '').toUpperCase();
    const rejected = /\b(REJECTED|REJECT|NOT\s+APPROVED)\b/.test(upper);
    const approved = /\b(APPROVED|LGTM)\b/.test(upper);
    const finalApproved = approved && !rejected;
    return { approved: finalApproved, verdict: finalApproved ? 'APPROVED' : 'REJECTED' };
}

// Run an Agent and normalise the outcome; this never throws.
async function runAgent(agent, input) {
    try {
        const result = await agent.run(input);
        return {
            outputText: (result && result.outputText) || '',
            status: (result && result.status) || 'unknown',
            error: (result && result.error) || null
        };
    } catch (error) {
        return { outputText: '', status: 'error', error };
    }
}

