21 |     const bin = tokens[0];
22 |     const rawArgs = tokens.slice(1);
23 | 
24 |     const args = rawArgs.map((arg) => {
25 |         if (arg.startsWith('-')) return arg; // flag, e.g. -m, -q, -v
26 |         const looksLikePath = arg.includes('/') || arg.endsWith('.py');
27 |         if (!looksLikePath) return arg; // module / test name -> leave verbatim
28 |         return resolveInsideWorkspace(workspacePath, arg); // a real path -> sandbox it
29 |     });
