```js
import { execSync } from 'child_process';
import fs from 'fs';

const EMPTY = { diff: '', filesChanged: [] };

export function captureGitDiff(workspacePath) {
  try {
    if (!workspacePath || !fs.existsSync(workspacePath)) return { ...EMPTY };
  } catch { return { ...EMPTY }; }

  const run = (args) => {
    try {
      return execSync(`git ${args}`, { cwd: workspacePath, encoding: 'utf-8', stdio: ['ignore','pipe','pipe'], timeout: 20000 });
    } catch { return ''; }
  };

  // Compare the working tree (staged + unstaged) against the initial commit.
  let diff = run('diff HEAD');
  if (!diff || diff.trim() === '') {
    diff = run('diff');           // unstaged only
  }
  if (!diff || diff.trim() === '') {
    diff = run('diff --cached');  // staged only
  }

  const clean = typeof diff === 'string' ? diff : '';
  return { diff: clean, filesChanged: parseFilesChanged(clean) };
}

export function parseFilesChanged(diff) {
  const files = new Set();
  const re = /^diff --git a\/(.+?) b\/(.+)$/gm;
  let match;
  while ((match = re.exec(diff)) !== null) {
    files.add(match[2]);
  }
  // Fallback: +++ b/path lines
  if (files.size === 0) {
    const re2 = /^\+\+\+ b\/(.+)$/gm;
    while ((match = re2.exec(diff)) !== null) files.add(match[1]);
  }
  return [...files];
}
```

