import { execSync } from 'child_process';
import fs from 'fs';

const EMPTY_DIFF = { diff: '', filesChanged: [] };

// Run a git command inside the workspace, never throwing.
function runGit(workspacePath, args) {
    try {
        return execSync(`git ${args}`, {
            cwd: workspacePath,
            encoding: 'utf-8',
            stdio: ['ignore', 'pipe', 'pipe'],
            timeout: 20000,
            maxBuffer: 10 * 1024 * 1024
        });
    } catch {
        return '';
    }
}

// Extract the list of changed files from a unified diff.
export function parseFilesChanged(diff) {
    const files = new Set();
    const text = typeof diff === 'string' ? diff : '';

    const header = /^diff --git a\/(.+?) b\/(.+)$/gm;
    let match;
    while ((match = header.exec(text)) !== null) {
        files.add(match[2]);
    }

    if (files.size === 0) {
        const target = /^\+\+\+ b\/(.+)$/gm;
        while ((match = target.exec(text)) !== null) {
            files.add(match[1]);
        }
    }

    return [...files];
}

/**
 * Capture the workspace's mutations against its baseline commit.
 * Compares staged + unstaged changes to the initial clone/import state.
 * Never throws: returns { diff: '', filesChanged: [] } when unavailable.
 */
export function captureGitDiff(workspacePath) {
    try {
        if (!workspacePath || !fs.existsSync(workspacePath)) return { ...EMPTY_DIFF };

        // Working tree (staged + unstaged) vs the baseline commit.
        let diff = runGit(workspacePath, 'diff HEAD');
        if (!diff || diff.trim() === '') diff = runGit(workspacePath, 'diff');
        if (!diff || diff.trim() === '') diff = runGit(workspacePath, 'diff --cached');

        const clean = typeof diff === 'string' ? diff : '';
        return { diff: clean, filesChanged: parseFilesChanged(clean) };
    } catch {
        return { ...EMPTY_DIFF };
    }
}

import fs from 'fs';
import path from 'path';

