// Helpers
// ---------------------------------------------------------------------------
function escapeHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function severityFor(mode) {
    return mode === 'security' ? 'HIGH' : 'MEDIUM';
}

function normalizeList(list, fallback) {
    const arr = Array.isArray(list) ? list.filter(Boolean) : [];
    return arr.length ? arr : fallback;
}

