```js
const TYPE_META = {
  investigator: { label: 'INVESTIGATOR', level: 'investigator' },
  reviewer: { label: 'QA REVIEWER', level: 'reviewer' },
  alert: { label: 'ALERT', level: 'alert' },
  success: { label: 'SUCCESS', level: 'success' },
  error: { label: 'ERROR', level: 'error' },
  info: { label: 'SYSTEM', level: 'system' },
  system: { label: 'SYSTEM', level: 'system' },
}

function metaFor(type) {
  return TYPE_META[type] || TYPE_META.system
}

function parseDiff(diffText) {
  const files = []
  let current = null
  const lines = String(diffText || '').split('\n')

  for (const raw of lines) {
    if (raw.startsWith('diff --git ')) {
      const match = /^diff --git a\/(.+?) b\/(.+)$/.exec(raw)
      current = { path: match ? match[2] : raw.slice(11), lines: [] }
      files.push(current)
      continue
    }
    if (raw === '') continue

    if (!current) {
      current = { path: '(workspace)', lines: [] }
      files.push(current)
    }

    let kind = 'context'
    if (
      raw.startsWith('@@') ) kind = 'hunk'
    else if (raw.startsWith('+++') || raw.startsWith('---') || raw.startsWith('index ') ||
             raw.startsWith('new file') || raw.startsWith('deleted file') ||
             raw.startsWith('similarity index') || raw.startsWith('rename ') ||
             raw.startsWith('old mode') || raw.startsWith('new mode'))
      kind = 'meta'
    else if (raw.startsWith('+')) kind = 'add'
    else if (raw.startsWith('-')) kind = 'del'

    current.lines.push({ kind, text: raw })
  }

  return files
}
```

Note: parseDiff skips empty lines ('') to keep it tidy — but that could drop spacing lines. Unified diff context lines start with ' ' (space), so truly empty lines mean '\ No newline at end of file' or blank separators. Skipping '' is fine.

