    if (raw.startsWith('diff --git ')) {
      const match = /^diff --git a\/(.+?) b\/(.+)$/.exec(raw)
      current = { path: match ? match[2] : raw.slice(11), lines: [] }
      files.push(current)
      continue
    }
    if (raw === '') continue
    if (!current) {
      current = { path: '(workspace)', lines: [] }
      files.push(current)
    }

    let kind = 'context'
    if (raw.startsWith('@@')) {
      kind = 'hunk'
    } else if (
      raw.startsWith('+++') || raw.startsWith('---') || raw.startsWith('index ') ||
      raw.startsWith('new file') || raw.startsWith('deleted file') ||
      raw.startsWith('similarity index') || raw.startsWith('rename ') ||
      raw.startsWith('old mode') || raw.startsWith('new mode')
    ) {
      kind = 'meta'
    } else if (raw.startsWith('+')) {
      kind = 'add'
    } else if (raw.startsWith('-')) {
      kind = 'del'
    }

    current.lines.push({ kind, text: raw })
  }

  return files
}

