      socket = new WebSocket(SERVER_WS)
    } catch (err) {
      // Defer UI update out of the synchronous effect body (react-hooks/set-state-in-effect)
      queueMicrotask(() => {
        pushLog('error', `Unable to open telemetry socket: ${err.message}`)
        setLinkState('closed')
      })
      return undefined
    }

    socket.onopen = () => setLinkState('open')
    socket.onclose = () => setLinkState('closed')
    socket.onerror = () => setLinkState('error')

    socket.onmessage = (event) => {
      let payload
      try {
        payload = JSON.parse(event.data)
      } catch {
        pushLog('info', String(event.data))
        return
      }

      pushLog(payload?.type, payload?.message ?? String(event.data))

      if (payload?.type === 'success') {
        setInvestigating(false)
        if (payload.workspaceId) {
          setMissionId(payload.workspaceId)
          fetchDiff(payload.workspaceId)
        }
      } else if (payload?.type === 'error') {
        setInvestigating(false)
      }
    }

    return () => socket.close()
  }, [pushLog, fetchDiff])

