import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import './App.css'

const SERVER_HTTP = 'http://localhost:3001'
const SERVER_WS = 'ws://localhost:3001/stream'

// WebSocket event type -> visual identity (badge label + colour class)
const TYPE_META = {
  investigator: { label: 'INVESTIGATOR', level: 'investigator' },
  reviewer: { label: 'QA REVIEWER', level: 'reviewer' },
  alert: { label: 'ALERT', level: 'alert' },
  success: { label: 'SUCCESS', level: 'success' },
  error: { label: 'ERROR', level: 'error' },
  info: { label: 'SYSTEM', level: 'system' },
  system: { label: 'SYSTEM', level: 'system' },
}

function metaFor(type) {
  return TYPE_META[type] || TYPE_META.system
}

// Lightweight, zero-dependency unified-diff parser.
function parseDiff(diffText) {
  const files = []
  let current = null

  for (const raw of String(diffText || '').split('\n')) {
    if (raw.startsWith('diff --git ')) {
      const match = /^diff --git a\/(.+?) b\/(.+)$/.exec(raw)
      current = { path: match ? match[2] : raw.slice(11), lines: [] }
      files.push(current)
      continue
    }

    if (raw === '') continue

    if (!current) {
      current = { path: '(workspace)', lines: [] }
      files.push(current)
    }

    let kind = 'context'
    if (raw.startsWith('@@')) {
      kind = 'hunk'
    } else if (
      raw.startsWith('+++') ||
      raw.startsWith('---') ||
      raw.startsWith('index ') ||
      raw.startsWith('new file') ||
      raw.startsWith('deleted file') ||
      raw.startsWith('similarity index') ||
      raw.startsWith('rename ') ||
      raw.startsWith('old mode') ||
      raw.startsWith('new mode')
    ) {
      kind = 'meta'
    } else if (raw.startsWith('+')) {
      kind = 'add'
    } else if (raw.startsWith('-')) {
      kind = 'del'
    }

    // Strip the leading +/-/space marker; the gutter renders it instead.
    const text = kind === 'add' || kind === 'del' || kind === 'context' ? raw.slice(1) : raw
    current.lines.push({ kind, text })
  }

  return files
}

function App() {
  const [logs, setLogs] = useState([])
  const [linkState, setLinkState] = useState('connecting')

  // Source selection
  const [source, setSource] = useState('zip') // 'zip' | 'git'
  const [zipFile, setZipFile] = useState(null)
  const [repoUrl, setRepoUrl] = useState('')

  // Incident configuration
  const [file, setFile] = useState('src/cart.js')
  const [line, setLine] = useState('3')
  const [errorType, setErrorType] = useState('TypeError')
  const [runtime, setRuntime] = useState('node') // 'node' | 'python'
  const [mode, setMode] = useState('reliability') // 'reliability' | 'security'
  const [testCommand, setTestCommand] = useState('')

  const [deploying, setDeploying] = useState(false)
  const [investigating, setInvestigating] = useState(false)
  const [workspace, setWorkspace] = useState(null) // { id, path } from ingest
  const [missionId, setMissionId] = useState(null) // workspaceId announced on success
  const [diffText, setDiffText] = useState('')
  const [filesChanged, setFilesChanged] = useState([])
  const [diffLoading, setDiffLoading] = useState(false)
  const [diffError, setDiffError] = useState('')

  const terminalRef = useRef(null)
  const idRef = useRef(0)

  const pushLog = useCallback((type, message) => {
    const meta = metaFor(type)
    setLogs((prev) => [
      ...prev,
      {
        id: (idRef.current += 1),
        level: meta.level,
        badge: meta.label,
        message,
        time: new Date().toLocaleTimeString('en-GB', { hour12: false }),
      },
    ])
  }, [])

// __APP_CHUNK_2__

  // Fetch the unified diff for a finished mission
  const fetchDiff = useCallback(async (workspaceId) => {
    setDiffLoading(true)
    setDiffError('')
    try {
      const response = await fetch(`${SERVER_HTTP}/diff/${workspaceId}`)
      const data = await response.json().catch(() => ({}))
      if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`)
      setDiffText(data.diff || '')
      setFilesChanged(Array.isArray(data.filesChanged) ? data.filesChanged : [])
    } catch (err) {
      setDiffError(err.message)
    } finally {
      setDiffLoading(false)
    }
  }, [])

  // Live telemetry: hold a WebSocket open to the autonomous engine
  useEffect(() => {
    let socket
    try {
      socket = new WebSocket(SERVER_WS)
    } catch (err) {
      // Defer UI update out of the synchronous effect body (react-hooks/set-state-in-effect)
      queueMicrotask(() => {
        pushLog('error', `Unable to open telemetry socket: ${err.message}`)
        setLinkState('closed')
      })
      return undefined
    }

    socket.onopen = () => setLinkState('open')
    socket.onclose = () => setLinkState('closed')
    socket.onerror = () => setLinkState('error')

    socket.onmessage = (event) => {
      let payload
      try {
        payload = JSON.parse(event.data)
      } catch {
        pushLog('info', String(event.data))
        return
      }

      pushLog(payload?.type, payload?.message ?? String(event.data))

      if (payload?.type === 'success') {
        setInvestigating(false)
        if (payload.workspaceId) {
          setMissionId(payload.workspaceId)
          fetchDiff(payload.workspaceId)
        }
      } else if (payload?.type === 'error') {
        setInvestigating(false)
      }
    }

    return () => socket.close()
  }, [pushLog, fetchDiff])

  // Auto-scroll: lock the terminal to the newest entry
  useEffect(() => {
    const terminal = terminalRef.current
    if (terminal) {
      terminal.scrollTop = terminal.scrollHeight
    }
  }, [logs])

  // Small JSON POST helper
  const postJson = useCallback(async (url, body) => {
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    })
    const data = await response.json().catch(() => ({}))
    if (!response.ok) {
      throw new Error(data.error || data.status || `HTTP ${response.status}`)
    }
    return data
  }, [])

// __APP_CHUNK_3__

