  // Ingest the codebase, capture the workspace, then auto-trigger the agent
  const handleDeploy = useCallback(
    async (event) => {
      event.preventDefault()
      if (deploying || investigating) return

      setDeploying(true)
      setWorkspace(null)
      setMissionId(null)
      setDiffText('')
      setFilesChanged([])
      setDiffError('')
      pushLog('system', '→ Deploying agent...')

      try {
        let ingest

        if (source === 'zip') {
          if (!zipFile) throw new Error('Choose a .zip archive to upload.')
          const form = new FormData()
          form.append('file', zipFile)
          pushLog('info', `📤 Uploading ${zipFile.name}...`)
          const response = await fetch(`${SERVER_HTTP}/ingest/zip`, {
            method: 'POST',
            body: form,
          })
          ingest = await response.json().catch(() => ({}))
          if (!response.ok) throw new Error(ingest.error || `HTTP ${response.status}`)
        } else {
          if (!repoUrl.trim()) throw new Error('Enter a public Git repository URL.')
          pushLog('info', `📤 Cloning ${repoUrl.trim()}...`)
          ingest = await postJson(`${SERVER_HTTP}/ingest/git`, { repoUrl: repoUrl.trim() })
        }

        const { workspaceId, workspacePath } = ingest
        setWorkspace({ id: workspaceId, path: workspacePath })
        pushLog('info', `📦 Workspace ready: ${workspaceId}`)

        setInvestigating(true)
        await postJson(`${SERVER_HTTP}/trigger`, {
          workspacePath,
          file: file.trim(),
          line: Number(line) || 1,
          errorType: errorType.trim() || 'Error',
          mode,
          runtime,
          testCommand: testCommand.trim(),
        })
        pushLog('success', `🚀 Agent deployed — [${mode}/${runtime}] streaming telemetry...`)
      } catch (err) {
        setInvestigating(false)
        pushLog('error', `✖ Deploy failed: ${err.message}`)
      } finally {
        setDeploying(false)
      }
    },
    [
      deploying,
      investigating,
      source,
      zipFile,
      repoUrl,
      file,
      line,
      errorType,
      mode,
      runtime,
      testCommand,
      postJson,
      pushLog,
    ],
  )

