function parseVerdict(text) {
    const raw = String(text || '');
    // Remove markdown emphasis so **VERDICT: APPROVED** / _REJECTED_ still match.
    const cleaned = raw.replace(/[*_`~]/g, ' ');

    // 1) Explicit "VERDICT ... APPROVED|REJECTED" - take the LAST one in the reply.
    const verdictRe = /VERDICT\s*[:\-\u2013\u2014]?\s*(APPROVED|REJECTED)\b/gi;
    let match;
    let last = null;
    while ((match = verdictRe.exec(cleaned)) !== null) {
        last = match[1].toUpperCase();
    }
    if (last) return { approved: last === 'APPROVED', verdict: last };

    // 2) Look for a bare verdict token near the end of the reply.
    const tail = cleaned
        .split('\n')
        .map((line) => line.trim())
        .filter(Boolean)
        .slice(-6)
        .join(' ')
        .toUpperCase();
    const tailRejected = /\b(REJECTED|REJECT|DENIED|NOT\s+APPROVED)\b/.test(tail);
    const tailApproved = /\b(APPROVED|APPROVE|LGTM)\b/.test(tail);
    if (tailApproved && !tailRejected) return { approved: true, verdict: 'APPROVED' };
    if (tailRejected) return { approved: false, verdict: 'REJECTED' };

    // 3) Whole-text fallback.
    const upper = cleaned.toUpperCase();
