/* ============================================================
   MISSION 5 — Glassmorphism & micro-animations
   ============================================================ */

/* Deep, slow-moving mesh gradient background */
.mission-control {
  position: relative;
  isolation: isolate;
  background: #020617;
  color: #e2e8f0;
}

.mission-control::before {
  content: '';
  position: fixed;
  inset: -25%;
  z-index: -1;
  pointer-events: none;
  background:
    radial-gradient(38% 38% at 18% 22%, rgba(124, 58, 237, 0.35), transparent 72%),
    radial-gradient(34% 34% at 82% 18%, rgba(8, 145, 178, 0.3), transparent 70%),
    radial-gradient(42% 42% at 62% 88%, rgba(37, 99, 235, 0.28), transparent 74%),
    radial-gradient(30% 30% at 30% 78%, rgba(147, 51, 234, 0.22), transparent 70%);
  animation: meshDrift 24s ease-in-out infinite alternate;
  will-change: transform;
}

@keyframes meshDrift {
  0% {
    transform: translate3d(-4%, -2%, 0) scale(1.06);
  }
  50% {
    transform: translate3d(3%, 3%, 0) scale(1.14);
  }
  100% {
    transform: translate3d(-2%, 4%, 0) scale(1.08);
  }
}

/* Frosted-glass cards (only the key panels get backdrop blur) */
.mc-panel {
  background: rgba(15, 23, 42, 0.6);
  -webkit-backdrop-filter: blur(12px);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  box-shadow:
    0 24px 60px -34px rgba(0, 0, 0, 0.95),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

/* Light, high-contrast typography on top of the dark glass */
.mc-title {
  color: #f8fafc;
}

.mc-panel-title {
  color: #f1f5f9;
}

.mc-subtitle,
.mc-label,
.mc-panel-tag,
.mc-hint {
  color: #a5b4cf;
}

.mc-link {
  background: rgba(15, 23, 42, 0.55);
  border-color: rgba(255, 255, 255, 0.12);
}

/* Inputs and selectors blend into the glass */
.mc-input,
.mc-seg,
.mc-tabs {
  background: rgba(2, 6, 23, 0.55);
  border-color: rgba(255, 255, 255, 0.12);
}

.mc-input {
  color: #f1f5f9;
}

.mc-input::placeholder {
  color: #64748b;
}

/* Buttons animate via framer-motion; keep the layer GPU-friendly */
.mc-btn {
  will-change: transform;
}

/* Status beacon: pulsing radar dot */
.mc-radar {
  display: inline-block;
  width: 9px;
  height: 9px;
  margin-right: 8px;
  vertical-align: middle;
  border-radius: 50%;
  background: #22d3ee;
  box-shadow: 0 0 0 0 rgba(34, 211, 238, 0.65);
  animation: radarPulse 1.6s ease-out infinite;
}

@keyframes radarPulse {
  0% {
    box-shadow: 0 0 0 0 rgba(34, 211, 238, 0.6);
  }
  70% {
    box-shadow: 0 0 0 11px rgba(34, 211, 238, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(34, 211, 238, 0);
  }
}

/* Blinking block cursor for the live terminal feed */
.mc-block {
  display: inline-block;
  margin-left: 3px;
  color: #22d3ee;
  text-shadow: 0 0 8px rgba(34, 211, 238, 0.8);
  animation: blockBlink 1.05s steps(1, end) infinite;
}

@keyframes blockBlink {
  0%,
  49% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}

/* Respect users who prefer reduced motion */
@media (prefers-reduced-motion: reduce) {
  .mission-control::before,
  .mc-radar,
  .mc-block {
    animation: none;
  }
}

