// Assign new-file line numbers to parsed diff lines (render-only; parseDiff is untouched).
function annotateLineNumbers(lines) {
  let newLine = 0
  return lines.map((entry) => {
    if (entry.kind === 'hunk') {
      const match = /^@@\s+-\d+(?:,\d+)?\s+\+(\d+)/.exec(entry.text)
      if (match) newLine = Number(match[1])
      return { ...entry, lineNo: '' }
    }
    if (entry.kind === 'meta' || entry.kind === 'del') {
      return { ...entry, lineNo: '' }
    }
    const lineNo = newLine > 0 ? String(newLine) : ''
    newLine += 1
    return { ...entry, lineNo }
  })
}

