/* ---------- Segmented toggles (sleek pill bar) ---------- */
.mc-seg,
.mc-tabs {
  gap: 4px;
  padding: 4px;
  border-radius: 999px;
  background: rgba(2, 6, 23, 0.55);
  border: 1px solid var(--glass-border);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}

.mc-seg-btn,
.mc-tab {
  border-radius: 999px;
  background: transparent;
  border: 1px solid transparent;
  color: var(--slate-400);
  font-family: var(--font-sans);
  font-weight: 500;
  letter-spacing: 0.04em;
  transition: color 0.22s ease, background 0.22s ease, border-color 0.22s ease,
    box-shadow 0.22s ease;
}

.mc-seg-btn:hover,
.mc-tab:hover {
  color: #e2e8f0;
}

.mc-seg-btn.is-active,
.mc-tab.is-active {
  color: #bae6fd;
  background: rgba(6, 182, 212, 0.15);
  border-color: rgba(6, 182, 212, 0.65);
  box-shadow: 0 0 16px rgba(6, 182, 212, 0.28), inset 0 0 10px rgba(6, 182, 212, 0.12);
  text-shadow: 0 0 10px rgba(6, 182, 212, 0.6);
}

.mc-seg-btn--security.is-active {
  color: #fecdd3;
  background: rgba(244, 63, 94, 0.15);
  border-color: rgba(244, 63, 94, 0.65);
  box-shadow: 0 0 16px rgba(244, 63, 94, 0.28), inset 0 0 10px rgba(244, 63, 94, 0.12);
  text-shadow: 0 0 10px rgba(244, 63, 94, 0.6);
}

/* ---------- Custom file dropzone ---------- */
.mc-dropzone {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  border-radius: 14px;
  border: 1px dashed rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.5);
  cursor: pointer;
  transition: border-color 0.22s ease, box-shadow 0.22s ease, background 0.22s ease;
}

.mc-dropzone:hover,
.mc-dropzone:focus-within {
  border-color: rgba(6, 182, 212, 0.6);
  background: rgba(6, 182, 212, 0.06);
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.12);
}

.mc-dropzone.has-file {
  border-style: solid;
  border-color: rgba(16, 185, 129, 0.5);
  background: rgba(16, 185, 129, 0.06);
}

.mc-file-hidden {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

.mc-dropzone-icon {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  flex: none;
  border-radius: 10px;
  color: var(--accent-cyan);
  background: rgba(6, 182, 212, 0.1);
  border: 1px solid rgba(6, 182, 212, 0.3);
}

.mc-dropzone-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 13px;
  color: #e2e8f0;
}

.mc-dropzone-text small {
  font-size: 11.5px;
  color: var(--slate-500);
}

.mc-file-name {
  margin-left: auto;
  padding: 4px 10px;
  font-size: 11px;
  color: #bbf7d0;
  border-radius: 999px;
  border: 1px solid rgba(16, 185, 129, 0.4);
  background: rgba(16, 185, 129, 0.12);
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---------- Form fields ---------- */
.mc-label {
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--slate-400);
}

.mc-input {
  background: rgba(15, 23, 42, 0.8);
  border: 1px solid var(--glass-border);
  border-radius: 11px;
  color: #cbd5e1;
  font-size: 13px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.mc-input:focus {
  outline: none;
  border-color: var(--accent-cyan);
  background: rgba(15, 23, 42, 0.95);
  box-shadow: 0 0 0 3px rgba(6, 182, 212, 0.18), 0 0 18px rgba(6, 182, 212, 0.18);
}

/* ---------- Buttons ---------- */
.mc-btn {
  font-family: var(--font-sans);
  font-weight: 600;
  border-radius: 12px;
}

.mc-btn--cta {
  color: #03151b;
  font-weight: 700;
  letter-spacing: 0.03em;
  border: none;
  background: linear-gradient(135deg, #22d3ee 0%, #06b6d4 45%, #0e7490 100%);
  box-shadow: 0 4px 20px rgba(6, 182, 212, 0.4);
}

.mc-btn--cta:disabled {
  opacity: 0.72;
  cursor: progress;
}

.mc-spinner {
  width: 15px;
  height: 15px;
  flex: none;
  border-radius: 50%;
  border: 2px solid rgba(3, 21, 27, 0.35);
  border-top-color: #03151b;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

