/* ---------- Terminal window chrome ---------- */
.mc-term-chrome {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 11px 16px;
  margin-bottom: 12px;
  border-radius: 12px;
  border: 1px solid var(--glass-border);
  background: rgba(2, 6, 23, 0.6);
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
}

.mc-term-dots {
  display: inline-flex;
  gap: 7px;
}

.mc-dot {
  display: inline-block;
  width: 11px;
  height: 11px;
  border-radius: 50%;
}

.mc-dot--red {
  background: #ef4444;
  box-shadow: 0 0 8px rgba(239, 68, 68, 0.6);
}

.mc-dot--amber {
  background: #f59e0b;
  box-shadow: 0 0 8px rgba(245, 158, 11, 0.6);
}

.mc-dot--green {
  background: #10b981;
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.6);
}

.mc-term-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: #e2e8f0;
}

.mc-term-session {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--slate-500);
}

.mc-term-session-id {
  padding: 2px 8px;
  border-radius: 6px;
  border: 1px solid var(--glass-border);
  background: rgba(15, 23, 42, 0.7);
  color: #7dd3fc;
}

.mc-term-session-count {
  color: var(--slate-400);
}

/* ---------- Log stream ---------- */
.mc-terminal {
  background: rgba(2, 6, 23, 0.65);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  font-size: 13px;
  line-height: 1.7;
}

.log-badge {
  padding: 1px 9px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.06em;
}

.log-badge--investigator {
  color: #67e8f9;
  border-color: rgba(6, 182, 212, 0.5);
  background: rgba(6, 182, 212, 0.14);
}

.log-badge--reviewer {
  color: #c4b5fd;
  border-color: rgba(167, 139, 250, 0.5);
  background: rgba(167, 139, 250, 0.14);
}

.log-badge--alert,
.log-badge--error {
  color: #fda4af;
  border-color: rgba(244, 63, 94, 0.5);
  background: rgba(244, 63, 94, 0.14);
}

.log-badge--success {
  color: #6ee7b7;
  border-color: rgba(16, 185, 129, 0.5);
  background: rgba(16, 185, 129, 0.14);
}

.log-badge--system {
  color: #cbd5e1;
  border-color: rgba(148, 163, 184, 0.4);
  background: rgba(148, 163, 184, 0.12);
}

.log-line--investigator {
  color: #67e8f9;
}

.log-line--reviewer {
  color: #c4b5fd;
}

.log-line--alert,
.log-line--error {
  color: #fda4af;
}

.log-line--success {
  color: #6ee7b7;
}

.log-line--system,
.log-line--info {
  color: #cbd5e1;
}

/* ---------- Diff viewer ---------- */
.mc-diff {
  background: rgba(2, 6, 23, 0.7);
  border: 1px solid var(--glass-border);
  border-radius: 12px;
  font-size: 12.5px;
  line-height: 1.6;
}

.diff-lineno {
  flex: none;
  width: 46px;
  padding-right: 12px;
  text-align: right;
  color: #475569;
  user-select: none;
}

.diff-file-head {
  background: rgba(15, 23, 42, 0.9);
  border-bottom: 1px solid var(--glass-border);
  color: #bae6fd;
}

.diff-line--add {
  background: rgba(6, 78, 59, 0.45);
  color: #bbf7d0;
  box-shadow: inset 3px 0 0 rgba(16, 185, 129, 0.7);
}

.diff-line--del {
  background: rgba(69, 10, 10, 0.42);
  color: #fecdd3;
  box-shadow: inset 3px 0 0 rgba(244, 63, 94, 0.7);
}

.diff-file-chip {
  color: #bae6fd;
  background: rgba(6, 182, 212, 0.12);
  border: 1px solid rgba(6, 182, 212, 0.35);
}

/* ---------- Enterprise artifact buttons ---------- */
.mc-btn--success {
  color: #04120c;
  border: none;
  background: linear-gradient(135deg, #34d399 0%, #10b981 55%, #047857 100%);
  box-shadow: 0 4px 20px rgba(16, 185, 129, 0.35);
}

.mc-btn--ghost {
  color: #c7f9ff;
  border: 1px solid rgba(6, 182, 212, 0.45);
  background: rgba(6, 182, 212, 0.08);
  box-shadow: 0 4px 18px rgba(6, 182, 212, 0.2);
}

/* ---------- Responsive ---------- */
@media (max-width: 640px) {
  .mc-title-row {
    flex-wrap: wrap;
  }

  .mc-term-title {
    display: none;
  }
}

