// Percent-encode only the characters that would otherwise break an HTTPS URL's
// userinfo component. Common PATs (ghp_…, glpat-…, …) pass through untouched.
function encodeUserInfo(secret) {
    if (/^[A-Za-z0-9._~-]+$/.test(secret)) return secret;
    return secret.replace(/[^A-Za-z0-9._~-]/g, (char) => encodeURIComponent(char));
}

