// Non-HTTPS URLs (ssh://, git@…) are returned unchanged (tokens are only supported
// for HTTPS remotes). An existing userinfo component is replaced.
function withGitToken(repoUrl, token) {
    const url = String(repoUrl || '').trim();
    const secret = String(token || '').trim();
    if (!secret) return url;
    if (!/^https:\/\//i.test(url)) return url;
    const rest = url.slice('https://'.length).replace(/^[^@/]*@/, '');
    return `https://${encodeUserInfo(secret)}@${rest}`;
