// ---------------------------------------------------------------------------
// Private repository support (Personal Access Tokens)
// ---------------------------------------------------------------------------

// Percent-encode only the characters that would otherwise break an HTTPS URL's
// userinfo component. Common PATs (ghp_…, glpat-…, …) pass through untouched.
function encodeUserInfo(secret) {
    if (/^[A-Za-z0-9._~-]+$/.test(secret)) return secret;
    return secret.replace(/[^A-Za-z0-9._~-]/g, (char) => encodeURIComponent(char));
}

// Inject a token into an HTTPS git URL: https://host/path -> https://TOKEN@host/path
// Works for GitHub, GitLab and Bitbucket. Non-HTTPS remotes (ssh://, git@…) are
// returned unchanged because tokens are only supported for HTTPS. Any existing
// userinfo component is replaced.
function withGitToken(repoUrl, token) {
    const url = String(repoUrl || '').trim();
    const secret = String(token || '').trim();
    if (!secret) return url;
    if (!/^https:\/\//i.test(url)) return url;
    const rest = url.slice('https://'.length).replace(/^[^@/]*@/, '');
    return `https://${encodeUserInfo(secret)}@${rest}`;
}

// Strip every occurrence of the given secrets from a string BEFORE it is logged,
// returned to the client, or broadcast over the WebSocket. Also covers the
// percent-encoded form of the token.
function redactSecrets(text, secrets) {
    let out = String(text ?? '');
    for (const secret of secrets) {
        const value = String(secret || '').trim();
        if (!value) continue;
        out = out.split(value).join('***');
        const encoded = encodeUserInfo(value);
        if (encoded !== value) out = out.split(encoded).join('***');
    }
    return out;
}

// Does this git error indicate an authentication / authorization failure?
function looksLikeAuthFailure(detail) {
    return /(403|404|authentication failed|could not read username|terminal prompts disabled|access denied|repository not found|not found)/i.test(
        String(detail || '')
    );
}

// 4. Ingest a .zip archive into a fresh isolated workspace

// 5. Ingest a Git repository (public, or private with a Personal Access Token)
fastify.post('/ingest/git', async (request, reply) => {
    const repoUrl = request.body?.repoUrl;
    const gitToken = request.body?.gitToken;

    if (typeof repoUrl !== 'string' || repoUrl.trim() === '') {
        return reply.code(400).send({ status: 'failed', error: 'repoUrl is required.' });
    }

    // Reject shell metacharacters / unexpected schemes before handing the URL to git
    const UNSAFE = /[\s"'`$&|;<>(){}\\]/;
    if (UNSAFE.test(repoUrl) || !/^(https?:\/\/|git@|ssh:\/\/|git:\/\/)/.test(repoUrl)) {
        return reply.code(400).send({ status: 'failed', error: 'Unsupported or unsafe repoUrl.' });
    }

    // The token lives only in memory, only for the duration of this clone.
    const token = typeof gitToken === 'string' ? gitToken.trim() : '';
    const cloneUrl = withGitToken(repoUrl, token);
    // Anything we might surface must be scrubbed of these values first.
    const secrets = token ? [token, cloneUrl] : [];

    const workspaceId = newWorkspaceId();
    const workspacePath = path.join(WORKSPACES_ROOT, workspaceId);

    try {
        // -c credential.helper= disables any OS credential store so the token is
        // never persisted outside this single execution.
        execSync(`git -c credential.helper= clone ${cloneUrl} ${workspacePath}`, {
            stdio: 'pipe',
            encoding: 'utf-8',
            // Never let git block waiting for credentials in a server context
            env: { ...process.env, GIT_TERMINAL_PROMPT: '0' }
        });
    } catch (error) {
        try { fs.rmSync(workspacePath, { recursive: true, force: true }); } catch { /* ignore */ }

        // error.message can contain the full (tokenised) command, so redact first.
        const rawDetail = error.stderr ? String(error.stderr).trim() : error.message;
        const detail = redactSecrets(rawDetail, secrets);

        if (looksLikeAuthFailure(detail)) {
            const message = token
                ? 'The provided Git Access Token was rejected. Check that it is valid and has read access to this repository.'
                : 'This repository looks private (or does not exist). Provide a valid Git Access Token to clone private repositories.';
            // Only the clean URL is ever broadcast — never the token.
            broadcast({ type: 'error', message: `❌ Git ingest failed: authentication required for ${repoUrl}.` });
            return reply.code(401).send({ status: 'failed', error: message });
        }

        broadcast({ type: 'error', message: `❌ Git ingest failed: ${detail}` });
        return reply.code(400).send({ status: 'failed', error: detail });
    }

    // `git clone` writes the tokenised URL into .git/config; rewrite it back to the
    // clean URL so no credential is left inside the workspace.
    if (token && /^https:\/\//i.test(repoUrl)) {
        try {
            execSync(`git -C ${workspacePath} remote set-url origin ${repoUrl}`, {
                stdio: 'pipe',
                encoding: 'utf-8',
                env: { ...process.env, GIT_TERMINAL_PROMPT: '0' }
            });
        } catch {
            /* best-effort: the workspace is disposable either way */
        }
    }

    broadcast({ type: 'info', message: `📦 Workspace ${workspaceId} staged from ${repoUrl}.` });
    return { workspaceId, workspacePath };
});

