  const buffer = fs.readFileSync(ZIP_PATH);
  const form = new FormData();
  form.append('file', new Blob([buffer], { type: 'application/zip' }), 'e2e-test-payload.zip');

  const ingestRes = await fetch(`${BASE}/ingest/zip`, { method: 'POST', body: form });
  const ingest = await ingestRes.json();
  if (!ingestRes.ok) throw new Error(`ingest failed (${ingestRes.status}): ${JSON.stringify(ingest)}`);
  const { workspaceId, workspacePath } = ingest;
  console.log(`      workspaceId   = ${workspaceId}`);
  console.log(`      workspacePath = ${workspacePath}`);

  // ---- 2. Install the workspace's test dependency (jest) --------------------
  console.log('\n[2/5] Installing workspace dependencies (jest) ...');
  execSync('npm install --no-audit --no-fund', { cwd: workspacePath, stdio: 'inherit' });

  // ---- 3. Subscribe to the telemetry stream ---------------------------------
  console.log('\n[3/5] Connecting to telemetry WebSocket ...');
  const ws = new WebSocket(WS_URL);
  let outcome = null;
  const settled = new Promise((resolve) => {
    ws.addEventListener('message', (event) => {
      let payload;
      try {
        payload = JSON.parse(event.data);
      } catch {
        payload = { type: 'raw', message: String(event.data) };
      }
      const tag = `[${String(payload.type).toUpperCase()}]`;
      console.log(`      ${tag} ${payload.message ?? ''}${payload.workspaceId ? ` (${payload.workspaceId})` : ''}`);
      if (payload.type === 'success' || payload.type === 'error') {
        outcome = payload;
        resolve(payload);
      }
    });
    ws.addEventListener('error', () => console.log('      ! WebSocket error'));
  });
  await new Promise((resolve) => ws.addEventListener('open', resolve));
  console.log('      telemetry socket open');

  // ---- 4. Trigger the multi-agent loop --------------------------------------
