    process.exit(1);
  }
  if (result.type !== 'success') {
    console.error(`\n[X] Mission ended with [${String(result.type).toUpperCase()}], not [SUCCESS].`);
    process.exit(1);
  }
  console.log('\n      ✔ SUCCESS signal received');

  // ---- 5. Verify the generated artifacts ------------------------------------
  console.log('\n[5/5] Verifying artifacts ...');
  const rcaRes = await fetch(`${BASE}/rca/${workspaceId}`);
  const rcaBody = await rcaRes.text();
  const diffRes = await fetch(`${BASE}/diff/${workspaceId}`);
  const diffJson = await diffRes.json();

