    console.log('\n✅ E2E PIPELINE VERIFIED: ingest -> dual-agent loop -> patch -> tests -> RCA -> diff\n');
    process.exit(0);
  }
  console.error('\n❌ E2E PIPELINE FAILED: artifacts did not validate.\n');
  process.exit(1);
}

